// tb_dynamic_v2_correctness.sv
//
// Post-v1: correctness check for the two v2-model runtime-scheduling
// programs (sim/programs/scheduler/dynamic_v2_demo.s and
// mixed_dynamic_v2_demo.s, generated by
// scheduler/runtime/gen_dynamic_v2_demo.py). They run exactly Phase
// 15's 6-workload and Phase 16's 12-workload streams, with the same
// unified per-block output layout, so the expected values are the same
// ones tb_dynamic_scheduler_correctness.sv and
// tb_mixed_workload_correctness.sv already check (computed in Python,
// see those files' headers). Only the runtime decision threshold
// differs -- which is exactly the code path this check exists to
// cover: vecadd N=2 now dispatches to the accelerator instead of the
// CPU, so its copy-out path is what produces that block's result here.

`timescale 1ns/1ps

module tb_dynamic_v2_correctness;

  logic clk;
  logic rst_n = 0;

  initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
  end

  int errors = 0;

  task automatic check(string name, logic [31:0] actual, logic [31:0] expected);
    if (actual !== expected) begin
      $display("  [FAIL] %-28s expected=%0d actual=%0d", name, expected, actual);
      errors++;
    end else begin
      $display("  [PASS] %-28s = %0d", name, actual);
    end
  endtask

  `define SOC_PORTS(gpio_out_sig) \
    .clk(clk), .rst_n(rst_n), .gpio_in(32'b0), .gpio_out(gpio_out_sig), \
    .uart_tx_valid(), .uart_tx_byte(), \
    .dbg_if_pc(), .dbg_if_instr(), .dbg_id_pc(), .dbg_id_instr(), \
    .dbg_ex_pc(), .dbg_ex_instr(), .dbg_mem_instr(), .dbg_wb_instr(), \
    .dbg_reg_write(), .dbg_rd_addr(), .dbg_rd_data(), \
    .dbg_illegal(), .dbg_stall(), .dbg_flush(), \
    .perf_cycle_count(), .perf_instr_retired_count(), .perf_stall_count(), \
    .perf_branch_count(), .perf_branch_taken_count(), .perf_load_use_stall_count(), \
    .perf_forwarding_event_count(), .perf_flush_count()

  logic [31:0] small_gpio, mixed_gpio;

  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/dynamic_v2_demo.hex"), .RAM_DEPTH_WORDS(4096))
    dut_small (`SOC_PORTS(small_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/mixed_dynamic_v2_demo.hex"), .RAM_DEPTH_WORDS(4096))
    dut_mixed (`SOC_PORTS(mixed_gpio));

  localparam int MAX_CYCLES = 20000;

  // RAM word index of block i's unified output base.
  function automatic int unsigned sbase(int i);  // Phase 15 layout: 0x3000 + i*0x80
    return 32'd3072 + i * 32'd32;
  endfunction
  function automatic int unsigned mbase(int i);  // Phase 16 layout: 0x3000 + i*0x100
    return 32'd3072 + i * 32'd64;
  endfunction

  initial begin
    $display("=== v2-model runtime scheduling correctness check ===");

    rst_n = 0;
    repeat (2) @(posedge clk);
    #1;
    rst_n = 1;

    repeat (MAX_CYCLES) @(posedge clk);
    #1;

    $display("");
    $display("--- dynamic_v2_demo (Phase 15 stream) ---");
    check("sentinel",            small_gpio, 32'hDEADBEEF);
    check("b0 vecadd1 [0]",      dut_small.ram_inst.mem[sbase(0)+0], 32'd3);
    check("b1 vecadd2 [0]",      dut_small.ram_inst.mem[sbase(1)+0], 32'd3);
    check("b1 vecadd2 [1]",      dut_small.ram_inst.mem[sbase(1)+1], 32'd5);
    check("b2 vecadd4 [0]",      dut_small.ram_inst.mem[sbase(2)+0], 32'd3);
    check("b2 vecadd4 [3]",      dut_small.ram_inst.mem[sbase(2)+3], 32'd9);
    check("b3 dot1",             dut_small.ram_inst.mem[sbase(3)+0], 32'd2);
    check("b4 dot4",             dut_small.ram_inst.mem[sbase(4)+0], 32'd40);
    check("b5 matmul2 [0]",      dut_small.ram_inst.mem[sbase(5)+0], 32'd8);
    check("b5 matmul2 [3]",      dut_small.ram_inst.mem[sbase(5)+3], 32'd18);

    $display("");
    $display("--- mixed_dynamic_v2_demo (Phase 16 stream) ---");
    check("sentinel",            mixed_gpio, 32'hDEADBEEF);
    check("b0 vecadd1 [0]",      dut_mixed.ram_inst.mem[mbase(0)+0],   32'd3);
    check("b1 vecadd2 [0]",      dut_mixed.ram_inst.mem[mbase(1)+0],   32'd3);
    check("b1 vecadd2 [1]",      dut_mixed.ram_inst.mem[mbase(1)+1],   32'd5);
    check("b2 dot4",             dut_mixed.ram_inst.mem[mbase(2)+0],   32'd40);
    check("b3 matmul2 [0]",      dut_mixed.ram_inst.mem[mbase(3)+0],   32'd8);
    check("b3 matmul2 [3]",      dut_mixed.ram_inst.mem[mbase(3)+3],   32'd18);
    check("b4 vecadd4 [0]",      dut_mixed.ram_inst.mem[mbase(4)+0],   32'd3);
    check("b4 vecadd4 [3]",      dut_mixed.ram_inst.mem[mbase(4)+3],   32'd9);
    check("b5 dot8",             dut_mixed.ram_inst.mem[mbase(5)+0],   32'd240);
    check("b6 vecadd8 [0]",      dut_mixed.ram_inst.mem[mbase(6)+0],   32'd3);
    check("b6 vecadd8 [7]",      dut_mixed.ram_inst.mem[mbase(6)+7],   32'd17);
    check("b7 matmul4 [0]",      dut_mixed.ram_inst.mem[mbase(7)+0],   32'd40);
    check("b7 matmul4 [15]",     dut_mixed.ram_inst.mem[mbase(7)+15],  32'd148);
    check("b8 dot16",            dut_mixed.ram_inst.mem[mbase(8)+0],   32'd1632);
    check("b9 vecadd16 [0]",     dut_mixed.ram_inst.mem[mbase(9)+0],   32'd3);
    check("b9 vecadd16 [15]",    dut_mixed.ram_inst.mem[mbase(9)+15],  32'd33);
    check("b10 dot32",           dut_mixed.ram_inst.mem[mbase(10)+0],  32'd11968);
    check("b11 vecadd32 [0]",    dut_mixed.ram_inst.mem[mbase(11)+0],  32'd3);
    check("b11 vecadd32 [31]",   dut_mixed.ram_inst.mem[mbase(11)+31], 32'd65);

    $display("");
    if (errors == 0) begin
      $display("RESULT: ALL CHECKS PASSED");
    end else begin
      $display("RESULT: %0d CHECK(S) FAILED", errors);
    end
    $finish;
  end

endmodule
